DROP TABLE IF EXISTS `pilkades`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `pilkades` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `desa_id` bigint unsigned NOT NULL,
  `tanggal_pemungutan` date NOT NULL,
  `total_tps` int NOT NULL DEFAULT '1',
  `total_dpt` int NOT NULL DEFAULT '0' COMMENT 'Jumlah DPT per desa',
  `calon_1_nama` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calon_2_nama` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `calon_3_nama` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `berita_acara_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pemenang_nama` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sk_bupati_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `disahkan_oleh` bigint unsigned DEFAULT NULL,
  `disahkan_at` timestamp NULL DEFAULT NULL,
  `status` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'persiapan',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `pilkades_desa_id_foreign` (`desa_id`),
  KEY `pilkades_disahkan_oleh_foreign` (`disahkan_oleh`),
  CONSTRAINT `pilkades_desa_id_foreign` FOREIGN KEY (`desa_id`) REFERENCES `desas` (`id`) ON DELETE CASCADE,
  CONSTRAINT `pilkades_disahkan_oleh_foreign` FOREIGN KEY (`disahkan_oleh`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

