DROP TABLE IF EXISTS `template_checklists`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `template_checklists` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `jenis_layanan_id` bigint unsigned NOT NULL,
  `alasan_pemberhentian_id` bigint unsigned DEFAULT NULL,
  `nama_dokumen` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `wajib` tinyint(1) NOT NULL DEFAULT '1',
  `urutan` int NOT NULL DEFAULT '0',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `template_checklists_jenis_layanan_id_foreign` (`jenis_layanan_id`),
  KEY `template_checklists_alasan_pemberhentian_id_foreign` (`alasan_pemberhentian_id`),
  CONSTRAINT `template_checklists_alasan_pemberhentian_id_foreign` FOREIGN KEY (`alasan_pemberhentian_id`) REFERENCES `alasan_pemberhentians` (`id`) ON DELETE CASCADE,
  CONSTRAINT `template_checklists_jenis_layanan_id_foreign` FOREIGN KEY (`jenis_layanan_id`) REFERENCES `jenis_layanans` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=832 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

